import{_ as e,o as a,c as o,ao as l}from"./chunks/framework.f3wvHiI1.js";const p=JSON.parse('{"title":"Example gallery","description":"","frontmatter":{},"headers":[],"relativePath":"examples/gallery.md","filePath":"examples/gallery.md","lastUpdated":null}'),r={name:"examples/gallery.md"};function i(n,t,s,d,h,g){return a(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="examples-gallery" tabindex="-1">Example gallery <a class="header-anchor" href="#examples-gallery" aria-label="Permalink to &quot;Example gallery {#examples-gallery}&quot;">​</a></h1><p>A guide answers <em>&quot;how do I do X&quot;</em>; an example answers <em>&quot;what does a real problem look like&quot;</em>. Each page here is a complete problem worked end to end: the problem, the direct method, the derivation of the solution from the maximum principle, the indirect method, and the comparison of the two, checked against the exact values when they are known.</p><p>Read them in order: each one uses something the previous ones introduced.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Example</th><th style="text-align:right;">Story</th><th style="text-align:right;">Introduces</th></tr></thead><tbody><tr><td style="text-align:right;"><a href="/OptimalControl.jl/previews/PR953/examples/double-integrator-energy#examples-double-integrator-energy">Energy minimisation</a></td><td style="text-align:right;">A wagon on a rail, transferred with the least energy.</td><td style="text-align:right;"><code>@def</code>, <code>solve</code>, <code>plot</code>, a Hamiltonian flow, shooting from the direct solution</td></tr><tr><td style="text-align:right;"><a href="/OptimalControl.jl/previews/PR953/examples/double-integrator-time#examples-double-integrator-time">Time minimisation (bang–bang)</a></td><td style="text-align:right;">The same wagon, with a bounded force, transferred as fast as possible.</td><td style="text-align:right;">a free final time, bang–bang control, the switching time read off the direct solution, concatenation of flows</td></tr><tr><td style="text-align:right;"><a href="/OptimalControl.jl/previews/PR953/examples/control-free#examples-control-free">Parameter estimation without a control</a></td><td style="text-align:right;">A growth rate fitted to data, and the pulsation of an oscillator, with no control.</td><td style="text-align:right;">problems without a control, the costate of the variable (<code>variable_costate=true</code>)</td></tr><tr><td style="text-align:right;"><a href="/OptimalControl.jl/previews/PR953/examples/control-and-variable#examples-control-and-variable">Control and variable together</a></td><td style="text-align:right;">The same two systems, with a control.</td><td style="text-align:right;">a parameter and a control optimised together, two extremals compared</td></tr><tr><td style="text-align:right;"><a href="/OptimalControl.jl/previews/PR953/examples/turnpike#examples-turnpike">Turnpike (bang–singular–bang)</a></td><td style="text-align:right;">A scalar system whose optimal control is bang, singular, then bang.</td><td style="text-align:right;">singular arcs, switching times as shooting unknowns, three flows concatenated</td></tr><tr><td style="text-align:right;"><a href="/OptimalControl.jl/previews/PR953/examples/singular-control#examples-singular-control">Singular control</a></td><td style="text-align:right;">A vehicle in a drift field, in minimum time.</td><td style="text-align:right;">the singular control by hand and with <code>Lift</code> and <code>@Lie</code></td></tr><tr><td style="text-align:right;"><a href="/OptimalControl.jl/previews/PR953/examples/state-constraint#examples-state-constraint">State constraint</a></td><td style="text-align:right;">The wagon with a speed limit, then with a bound on its position (Bryson–Denham).</td><td style="text-align:right;">boundary arcs, <code>constraint=</code> and <code>multiplier=</code>, touch points and costate jumps</td></tr><tr><td style="text-align:right;"><a href="/OptimalControl.jl/previews/PR953/examples/logo#examples-logo">The logo</a></td><td style="text-align:right;">A low-thrust orbit transfer, drawn three times.</td><td style="text-align:right;">an initial guess from an analytical trajectory, plotting with Makie</td></tr></tbody></table><h2 id="See-also" tabindex="-1">See also <a class="header-anchor" href="#See-also" aria-label="Permalink to &quot;See also {#See-also}&quot;">​</a></h2><ul><li><p><a href="/OptimalControl.jl/previews/PR953/flows/overview#flows-overview">Flows overview</a> and <a href="/OptimalControl.jl/previews/PR953/geometry/overview#geometry-overview">Geometry overview</a>: the tools these examples are built from.</p></li><li><p><a href="/OptimalControl.jl/previews/PR953/modelling/formulation#modelling-formulation-conventions">Notation and conventions</a>: the conventions of the derivations.</p></li></ul>',6)])])}const c=e(r,[["render",i]]);export{p as __pageData,c as default};
